function pad(n){ return String(n).padStart(2,'0'); }
function addDays(ymd,n){ var p=ymd.split('-'); var d=new Date(Date.UTC(+p[0],+p[1]-1,+p[2])); d.setUTCDate(d.getUTCDate()+n); return d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1)+'-'+pad(d.getUTCDate()); }
function dueDate(lmp){ if(!/^\d{4}-\d{2}-\d{2}$/.test(lmp)) return null; return addDays(lmp,280); }
function weeksBetween(a,b){ var pa=a.split('-'),pb=b.split('-'); var da=new Date(Date.UTC(+pa[0],+pa[1]-1,+pa[2])), db=new Date(Date.UTC(+pb[0],+pb[1]-1,+pb[2])); return Math.floor((db-da)/86400000/7); }
function gestation(lmp,ref){ var w=weeksBetween(lmp,ref); if(w<0) return null; return {weeks:w, trimester:(w<13)?1:(w<27)?2:3}; }
var EXPORTS={addDays:addDays,dueDate:dueDate,weeksBetween:weeksBetween,gestation:gestation};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DueDateForgePure = EXPORTS; }
